mapper.select:
select domain.id, domain.name, domain.version, domain.college_id, domain.major_id, domain.create_time,
domain.creator, domain.last_modified_time,domain.status,
domain.last_modifier, domain.remark, domain.sysflag,major.name major_name,
category.id category_id,category.name category_name,domain.source_id
from t_csys_source_domain domain
left join t_csys_std_major major
on domain.major_id = major.id
left join t_csys_training_scheme_category category
on domain.category_Id = category.id


        and domain.name like concat('%', #{name}, '%')


        and domain.college_id = #{collegeId}


        and domain.major_id = #{majorId}


        and domain.category_Id = #{categoryId}


        and domain.version = #{version}


        and domain.creator = #{creator}


        and domain.last_modifier = #{lastModifier}


        and domain.sysflag = #{sysflag}


        and domain.status = #{status}


        and domain.type = #{type}


order by domain.id desc

select domain.id, domain.name, domain.college_id, domain.major_id,domain.version,domain.type type, domain.create_time, domain.creator, domain.last_modified_time, domain.last_modifier, domain.remark, domain.sysflag,domain.status, unit.name unit_name,point.name point_name,unit.id unit_id,point.id point_id, category.id category_id,category.name category_name from t_csys_source_domain domain left join t_csys_source_domain_ref_unit domain_ref_unit on domain.id = domain_ref_unit.domain_id left join t_csys_source_unit unit on domain_ref_unit.unit_id = unit.id left join t_csys_source_unit_ref_point unit_ref_point on unit_ref_point.unit_id = unit.id left join t_csys_source_point point on unit_ref_point.point_id = point.id left join t_csys_training_scheme_category category on domain.category_Id = category.id where 1= 1
and domain.id in
#{id}
